declare const __BUILD_TIME__: string;
declare const __GIT_COMMIT__: string;
declare const __SCHEMA_VERSION__: number;
declare const __APP_EDITION__: string;
declare const __LICENSE_ID__: string;
declare const __LICENSE_URL__: string;
declare const __SOURCE_URL__: string;
declare const __DOCS_URL__: string;
declare const __HOMEPAGE_URL__: string;
declare const __TRADEMARK_NOTICE__: string;
